using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ScarletSigilCustomTag", menuName = "Data/Battle/Battle Actions/Tags/ScarletSigilCustomTag", order = 0)]
public class ScarletSigilCustomTag : CreatureWithEffectCustomTag
{
	[SerializeField]
	private DiceTier riskyDiceTier;

	public override string GetTagDescription()
	{
		return Smart.Format(GetCreatureWithEffectDescription(), GetTagName(), GetPurifyCorruptName(), Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedWheneverYouPlayA().LowercaseFirst().RemoveLast(), riskyDiceTier.GetLocalizedDiceTierWithDie()));
	}
}
